// Migrations for the Application's own database, generated by drizzle-kit
// from src/db/schema.ts.
import { cpSync, existsSync, mkdirSync, readdirSync, readFileSync, rmSync } from "node:fs";
import { join, relative } from "node:path";
import { runDrizzleKit } from "./pull.mjs";
import { VmError } from "./util.mjs";

export function journal(dir) {
  const f = join(dir, "meta", "_journal.json");
  return existsSync(f) ? JSON.parse(readFileSync(f, "utf8")).entries : [];
}

export function readMigration(dir, tag) {
  return readFileSync(join(dir, `${tag}.sql`), "utf8");
}

export function statements(sql) {
  return sql
    .split("--> statement-breakpoint")
    .map((s) => s.trim())
    .filter(Boolean);
}

/** What a migration destroys, in words. */
export function dataLoss(sql) {
  const found = [];
  for (const st of statements(sql)) {
    let m;
    const s = st.replace(/\s+/g, " ");
    if ((m = s.match(/^DROP TABLE (?:IF EXISTS )?"?(?:public"?\."?)?([\w]+)"?/i))) found.push(`drops table ${m[1]} and every row in it`);
    else if ((m = s.match(/^ALTER TABLE "?(?:public"?\."?)?(\w+)"? DROP COLUMN (?:IF EXISTS )?"?(\w+)"?/i))) found.push(`drops column ${m[1]}.${m[2]} and every value in it`);
    else if ((m = s.match(/^ALTER TABLE "?(?:public"?\."?)?(\w+)"? ALTER COLUMN "?(\w+)"? SET DATA TYPE (.+?);?$/i)))
      found.push(`changes the type of ${m[1]}.${m[2]} to ${m[3]}: values that do not convert are lost or make the migration fail`);
    else if ((m = s.match(/^DROP TYPE "?(?:public"?\."?)?(\w+)"?/i))) found.push(`drops type ${m[1]}`);
    else if ((m = s.match(/^DROP SCHEMA "?(\w+)"?/i))) found.push(`drops schema ${m[1]} and everything in it`);
    else if ((m = s.match(/^TRUNCATE (?:TABLE )?"?(\w+)"?/i))) found.push(`deletes every row of ${m[1]}`);
    else if ((m = s.match(/^DELETE FROM "?(\w+)"?/i))) found.push(`deletes rows of ${m[1]}`);
  }
  return found;
}

/** Runs drizzle-kit generate on a copy of migrations/ and reports what it would add. */
export function draft(root, { name } = {}) {
  const real = join(root, "migrations");
  const tmp = join(root, ".vm", "tmp", `migrations-${process.pid}-${Date.now()}`);
  mkdirSync(tmp, { recursive: true });
  if (existsSync(real)) cpSync(real, tmp, { recursive: true });
  const before = new Set(journal(tmp).map((e) => e.tag));
  const args = ["generate", "--dialect", "postgresql", "--schema", "./src/db/schema.ts", "--out", relative(root, tmp)];
  if (name) args.push("--name", name);
  const res = runDrizzleKit(args, { cwd: root });
  const output = `${res.stdout ?? ""}${res.stderr ?? ""}`;
  if (/Interactive prompts require a TTY/.test(output)) {
    rmSync(tmp, { recursive: true, force: true });
    const what = /promptColumnsConflicts/.test(output) ? "a column" : "a table";
    throw new VmError(
      [
        `src/db/schema.ts both removes ${what} and adds one, so the change might be a rename. Migrations cannot be generated for a rename.`,
        "Do it in steps that need no rename:",
        "  1. add the new one next to the old one, run `npx vm db generate`;",
        "  2. deploy, copy the values over in code, and switch the code to the new one;",
        "  3. remove the old one, run `npx vm db generate` (this destroys the old one's data, so the Builder must confirm).",
      ].join("\n"),
      { code: "rename" },
    );
  }
  if (res.status !== 0 || /Error/.test(res.stderr ?? "")) {
    rmSync(tmp, { recursive: true, force: true });
    throw new VmError(`Migrations could not be generated from src/db/schema.ts:\n${output.trim()}`, { code: "generate-failed" });
  }
  const added = journal(tmp)
    .filter((e) => !before.has(e.tag))
    .map((e) => ({ tag: e.tag, file: `migrations/${e.tag}.sql`, sql: readMigration(tmp, e.tag) }));
  for (const a of added) a.loses = dataLoss(a.sql);
  return {
    added,
    commit() {
      rmSync(real, { recursive: true, force: true });
      cpSync(tmp, real, { recursive: true });
      rmSync(tmp, { recursive: true, force: true });
    },
    discard() {
      rmSync(tmp, { recursive: true, force: true });
    },
  };
}

export function listMigrationFiles(root) {
  const dir = join(root, "migrations");
  if (!existsSync(dir)) return [];
  return readdirSync(dir).filter((f) => f.endsWith(".sql"));
}
